/**
 * Repeating-key XOR key for Homescapes `SaveGame.db` containers.
 *
 * EXTRACTED verbatim from the community decoder (`decode_savegame.py`,
 * `DEFAULT_KEY`, latin1-encoded). Stored base64 so no escape rules can
 * corrupt it. Status: UNVERIFIED — the only sample save available decodes as
 * plain JSON, so this key has never round-tripped a real encrypted file.
 *
 * Generated by tools/_extract_key.py. Do not hand-edit.
 */
export const XOR_KEY_B64 = "";
export const XOR_KEY_BYTES = 731;
export const XOR_KEY_SHA256 = "8eaa5f1d58665cb185338e20b63d87da98ae319aaa1d4285ca60ae051bedec09";

let cached: Uint8Array | null = null;

/** Decode the base64 key once and memoize it. Throws if the constant is corrupt. */
export function xorKey(): Uint8Array {
  if (cached) return cached;
  const bin = atob(XOR_KEY_B64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  if (out.length !== XOR_KEY_BYTES) {
    throw new Error(`XOR key length mismatch: ${out.length} != ${XOR_KEY_BYTES}`);
  }
  cached = out;
  return out;
}
